import type { GithubPullRequest, GithubPullRequestReviewSnapshot } from './github.js'
import { evaluateReviewGate } from './review-state.js'
import type { TaskRecord } from './state/model.js'

export type JudgeRejectionReason = {
  source: 'comment' | 'review'
  body: string
  authorLogin: string | null
  createdAt: string | null
}

export type JudgeDiscussionDirective =
  | {
      disposition: 'agree'
      body: string
    }
  | {
      disposition: 'disagree'
      body: string
    }
  | {
      disposition: 'unknown'
      body: string
    }

export function selectJudgePendingTasks(tasks: TaskRecord[], targetId: string): TaskRecord[] {
  return tasks.filter((task) => task.targetId === targetId && task.state === 'judge_pending' && Boolean(task.prNumber))
}

export function isRejectedPullRequest(pullRequest: GithubPullRequest): boolean {
  return Boolean(pullRequest.closedAt)
    && !pullRequest.mergedAt
    && hasPullRequestLabel(pullRequest, 'rejected')
}

export function isDuplicatePullRequest(pullRequest: GithubPullRequest): boolean {
  return Boolean(pullRequest.closedAt)
    && !pullRequest.mergedAt
    && hasPullRequestLabel(pullRequest, 'duplicate')
}

export function isChangesRequestedPullRequest(
  pullRequest: GithubPullRequest,
  snapshot: GithubPullRequestReviewSnapshot | null,
): boolean {
  if (pullRequest.mergedAt || pullRequest.closedAt) {
    return false
  }

  if (hasPullRequestLabel(pullRequest, 'changes-requested')) {
    return true
  }

  if (!snapshot) {
    return false
  }

  return evaluateReviewGate(snapshot).disposition === 'changes_requested'
}

export function extractLatestJudgeRejectionReason(snapshot: GithubPullRequestReviewSnapshot | null): JudgeRejectionReason | null {
  if (!snapshot) {
    return null
  }

  const entries = [
    ...snapshot.comments.map((comment, index) => ({
      source: 'comment' as const,
      body: comment.body.trim(),
      authorLogin: comment.authorLogin,
      createdAt: comment.createdAt,
      sortKey: buildSortKey(comment.createdAt, index),
    })),
    ...snapshot.reviews.map((review, index) => ({
      source: 'review' as const,
      body: review.body.trim(),
      authorLogin: review.authorLogin,
      createdAt: review.submittedAt,
      sortKey: buildSortKey(review.submittedAt, snapshot.comments.length + index),
    })),
  ]

  const latest = entries
    .filter((entry) => entry.body.length > 0 && !isCoordinatorGeneratedComment(entry.body))
    .sort((left, right) => right.sortKey - left.sortKey)[0]

  if (!latest) {
    return null
  }

  return {
    source: latest.source,
    body: latest.body,
    authorLogin: latest.authorLogin,
    createdAt: latest.createdAt,
  }
}

export function parseJudgeDiscussionDirective(message: string): JudgeDiscussionDirective {
  const trimmed = message.trim()
  const agreeMatch = trimmed.match(/^\[discussion-agent\]\s+Agree:\s*([\s\S]+)$/i)
  if (agreeMatch) {
    return {
      disposition: 'agree',
      body: (agreeMatch[1] ?? '').trim(),
    }
  }

  const disagreeMatch = trimmed.match(/^\[discussion-agent\]\s+Disagree:\s*([\s\S]+)$/i)
  if (disagreeMatch) {
    return {
      disposition: 'disagree',
      body: (disagreeMatch[1] ?? '').trim(),
    }
  }

  return {
    disposition: 'unknown',
    body: trimmed,
  }
}

function buildSortKey(timestamp: string | null, index: number): number {
  const parsed = timestamp ? Date.parse(timestamp) : Number.NaN
  if (Number.isFinite(parsed)) {
    return (parsed * 10_000) + index
  }
  return index
}

function isCoordinatorGeneratedComment(body: string): boolean {
  return /^\[(reviewer|implementer|coordinator)-agent\]/i.test(body.trim())
}

function hasPullRequestLabel(pullRequest: GithubPullRequest, expectedLabel: string): boolean {
  const normalizedExpectedLabel = expectedLabel.trim().toLowerCase()
  return pullRequest.labels.some((label) => label.trim().toLowerCase() === normalizedExpectedLabel)
}
